    #[expect(
        clippy::await_holding_invalid_type,
        reason = "catalog publication must wait for call preparation and execution"
    )]
    pub(crate) async fn run_with_snapshot<R, F, Fut>(
        &self,
        expected: &ToolCatalogSnapshot,
        run: F,
    ) -> Option<R>
    where
        F: FnOnce() -> Fut,
        Fut: Future<Output = R>,
    {
        let (current, snapshot) = self.read_current().await;
        if current.last_refresh_revision > expected.revision
            || (snapshot.revision != expected.revision
                && !catalogs_match(&snapshot.tools, &expected.tools))
        {
            return None;
        }
        let result = run().await;
        drop(current);
        Some(result)
    }
}

/// Compares complete definitions independently of tool-list order. Stable sorting keeps
/// conflicting duplicate identities in their original order, since deduplication can pick the
/// first definition. This slow path runs only after the client's revision has changed.
fn catalogs_match(left: &[ToolInfo], right: &[ToolInfo]) -> bool {
    if left == right {
        return true;
    }
    if left.len() != right.len() {
        return false;
    }
    let mut left = left.iter().collect::<Vec<_>>();
    let mut right = right.iter().collect::<Vec<_>>();
    for tools in [&mut left, &mut right] {
        tools.sort_by_key(|tool| {
            (
                tool.server_name.as_str(),
                tool.tool.name.as_ref(),
                tool.connector_id.as_deref(),
                tool.callable_namespace.as_str(),
                tool.callable_name.as_str(),
            )
        });
    }
    left == right

//! A startup ceiling on the tools a thread may advertise or execute.

use crate::ToolName;

/// Supply through `ExtensionDataInit` before starting a thread. The host captures
/// this value once; changing extension state later cannot widen the tool set.
/// Callers must supply it again when resuming a thread.
///
/// An absent value keeps ordinary tool setup. An empty list permits no tools.
/// Names include their namespace; a plain name uses the default namespace.
/// This only removes tools: configuration and permission checks still apply.
/// Generated tools such as Code Mode's `exec` and `wait` must also be listed.
#[derive(Clone, Debug, Default)]
pub struct AllowedTools(pub Vec<ToolName>);

impl AllowedTools {
    pub fn contains(&self, tool: &ToolName) -> bool {
        self.0.iter().any(|allowed| {
            allowed.name == tool.name
                && (allowed.namespace == tool.namespace
                    || (allowed.is_default_namespace() && tool.is_default_namespace()))
        })
    }
}

    /// A compatibility or extension registration without user-owned provenance.
    Other,
}

/// Read-only metadata and provenance captured from the MCP call that will execute.
#[derive(Clone, Debug)]
pub struct McpToolContext {
    tool: crate::McpToolInfo,
    source: McpToolSource,
}

impl McpToolContext {
    /// Snapshots a prepared call without exposing its executable client to extensions.
    ///
    /// Configured servers retain their provenance only when their captured connection
    /// still matches the host configuration for the current tool invocation.
    pub fn from_prepared_call(
        call: &PreparedMcpCall,
        configured_server: Option<&McpServerConfig>,
    ) -> Self {
        let tool = call.tool_info().clone();
        let registration = call.config().mcp_server_catalog.server(call.server_name());
        let source = if tool.connector_id.is_some() && call.is_host_owned_apps() {
            McpToolSource::Connector
        } else if call.is_selected_plugin_server() {
            McpToolSource::SelectedPlugin
        } else if let Some(McpServerSource::Plugin(plugin)) =
            registration.map(ResolvedMcpServer::source)
            && Some(plugin.plugin_id()) == call.plugin_id()
            && let Some(root) = plugin.host_root()
        {
            McpToolSource::Plugin {
                id: plugin.plugin_id().to_owned(),
                root: root.clone(),
            }
        } else if registration.is_some_and(|server| {
            matches!(server.source(), McpServerSource::Config)
                && configured_server.is_some_and(|configured| server.config() == configured)
        }) {
            McpToolSource::Config
        } else {
            McpToolSource::Other
        };

        Self { tool, source }
    }

    /// Returns frozen metadata for the exact model-visible MCP tool being executed.
    pub fn tool_info(&self) -> &crate::McpToolInfo {
        &self.tool
    }

    /// Returns the registration source captured with the executable call.
    pub fn source(&self) -> &McpToolSource {
        &self.source
    }
}

